BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS ADP_Nights_Clean (
    ADP_Nights_ID INTEGER PRIMARY KEY,

    RTO_Code INTEGER NOT NULL,

    Month TEXT NOT NULL,

    Property TEXT NOT NULL,

    Visitor_type TEXT NOT NULL
        CHECK (
            Visitor_type IN (
                'Domestic',
                'International'
            )
        ),

    Total_stay_nights INTEGER NOT NULL
        CHECK (Total_stay_nights >= 0),

    FOREIGN KEY (RTO_Code)
        REFERENCES RTO_Areas_Mapping_Clean(RTO_Code),

    UNIQUE (
        RTO_Code,
        Month,
        Property,
        Visitor_type
    )
);
CREATE TABLE IF NOT EXISTS RTO_Areas_Mapping_Clean (
    RTO_Code                   INTEGER PRIMARY KEY,
    RTO2025_V1_00_NAME         TEXT NOT NULL UNIQUE,
    RTO2025_V1_00_NAME_ASCII   TEXT,
    RTO_Label_2025             TEXT,
    RTO_Label_2025_ASCII       TEXT UNIQUE
);
CREATE TABLE IF NOT EXISTS Spend_Clean (
    Spend_ID INTEGER PRIMARY KEY,

    RTO_Code INTEGER NOT NULL,

    Month TEXT NOT NULL,

    Product TEXT NOT NULL,

    Visitor_type TEXT NOT NULL
        CHECK (
            Visitor_type IN (
                'Domestic',
                'International'
            )
        ),

    Origin TEXT NOT NULL,

    Annual_Spend_Million REAL,

    Monthly_Spend_Million REAL,

    FOREIGN KEY (RTO_Code)
        REFERENCES RTO_Areas_Mapping_Clean(RTO_Code),

    UNIQUE (
        RTO_Code,
        Month,
        Product,
        Visitor_type,
        Origin
    )
);
CREATE TABLE IF NOT EXISTS Visitor_Count_Clean (
    Visitor_Count_ID INTEGER PRIMARY KEY,

    RTO_Code INTEGER NOT NULL,

    Destination TEXT NOT NULL,

    Visitor_type TEXT NOT NULL
        CHECK (
            Visitor_type IN (
                'Domestic',
                'International'
            )
        ),

    Month TEXT NOT NULL,

    Visitor_count INTEGER NOT NULL
        CHECK (Visitor_count >= 0),

    FOREIGN KEY (RTO_Code)
        REFERENCES RTO_Areas_Mapping_Clean(RTO_Code),

    UNIQUE (
        RTO_Code,
        Visitor_type,
        Month
    )
);
COMMIT;
